/**
 * restructure-stratagem-store — one-time migration of the out-of-repo raw-text
 * store to the canonical stratagem shape: stratagem entries carry structured
 * `when`/`target`/`effect`/`restrictions` fields instead of a single `raw_text`
 * blob (cost is NOT stored — it lives in the core entity's `cp_cost`).
 *
 * Non-stratagem entries (unit abilities, enhancements) are single-prose and keep
 * `raw_text` unchanged. Parses the existing blob ("[N]CP. WHEN: … TARGET: …
 * EFFECT: … [RESTRICTIONS: …]") back into fields; anything it can't parse is left
 * as-is and reported (so no data is silently dropped).
 *
 * Usage: npx tsx tools/src/restructure-stratagem-store.ts [--store <dir>] [--dry-run]
 */
import { readFileSync, writeFileSync, existsSync, readdirSync } from "node:fs";
import { resolve, join } from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = fileURLToPath(new URL(".", import.meta.url));
const REPO = resolve(__dirname, "../..");
const args = process.argv.slice(2);
const flag = (n: string): string | undefined => { const i = args.indexOf(n); return i >= 0 ? args[i + 1] : undefined; };
const STORE_ROOT = resolve(REPO, flag("--store") ?? "../40kdc-abilities");
const DRY = args.includes("--dry-run");

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Json = any;
const clean = (s: string): string => String(s ?? "").replace(/\s+/g, " ").trim();

/** Split a stratagem blob into structured sections. Returns null if not parseable. */
export function parseStratagemBlob(raw: string): { when: string; target: string; effect: string; restrictions?: string } | null {
  const blob = String(raw ?? "");
  if (!/WHEN:/i.test(blob) && !/EFFECT:/i.test(blob)) return null;
  const grab = (label: RegExp, nexts: RegExp[]): string => {
    const m = blob.match(label);
    if (!m) return "";
    const rest = blob.slice(m.index! + m[0].length);
    let end = rest.length;
    for (const n of nexts) { const nm = rest.match(n); if (nm && nm.index! < end) end = nm.index!; }
    return clean(rest.slice(0, end));
  };
  const when = grab(/WHEN:/i, [/TARGET:/i, /EFFECT:/i, /RESTRICTIONS:/i]);
  const target = grab(/TARGET:/i, [/EFFECT:/i, /RESTRICTIONS:/i]);
  const effect = grab(/EFFECT:/i, [/RESTRICTIONS:/i]);
  const restrictions = grab(/RESTRICTIONS:/i, []);
  if (!when && !effect) return null;
  const out: { when: string; target: string; effect: string; restrictions?: string } = { when, target, effect };
  if (restrictions) out.restrictions = restrictions;
  return out;
}

const readJSON = (p: string): Json => JSON.parse(readFileSync(p, "utf-8"));
let converted = 0, skipped = 0, files = 0;
const unparseable: string[] = [];

for (const f of readdirSync(STORE_ROOT)) {
  if (!f.endsWith(".json") || f.startsWith("bundle-") || f === "index.json") continue;
  const p = join(STORE_ROOT, f);
  let arr: Json;
  try { arr = readJSON(p); } catch { continue; }
  if (!Array.isArray(arr)) continue;
  let changed = false;
  for (const e of arr) {
    if (e.ability_type !== "stratagem" || !("raw_text" in e)) continue;
    const sections = parseStratagemBlob(e.raw_text);
    if (!sections) { skipped++; unparseable.push(`${f}:${e.ability_id}`); continue; }
    e.when = sections.when;
    e.target = sections.target;
    e.effect = sections.effect;
    if (sections.restrictions) e.restrictions = sections.restrictions;
    delete e.raw_text;
    converted++; changed = true;
  }
  if (changed) { files++; if (!DRY) writeFileSync(p, JSON.stringify(arr, null, 2) + "\n"); }
}

console.log(`restructure: converted ${converted} stratagem entries across ${files} files; skipped (unparseable) ${skipped}${DRY ? "  (dry-run)" : ""}`);
if (unparseable.length) console.log("  unparseable:", unparseable.slice(0, 15).join(", ") + (unparseable.length > 15 ? ` … +${unparseable.length - 15}` : ""));
